// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.model.vocabulary.SPIN;
import org.eclipse.rdf4j.query.algebra.FunctionCall;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.evaluation.function.FunctionRegistry;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.ScalarEvaluationEffects.Effect;
import org.eclipse.rdf4j.spin.SpinParser;
import org.junit.jupiter.api.Test;

class EvalFunctionTest {

	@Test
	void expressionReadFromTheStoreCannotPromiseRepeatability() {
		assertThat(new EvalFunction(new SpinParser()).mustReturnDifferentResult()).isTrue();
	}

	@Test
	void registeredCallIsVolatile() {
		EvalFunction function = new EvalFunction(new SpinParser());
		FunctionRegistry.getInstance().add(function);
		try {
			FunctionCall call = new FunctionCall(SPIN.EVAL_FUNCTION.stringValue(),
					new ValueConstant(SimpleValueFactory.getInstance().createIRI("urn:test:expression")));

			assertThat(ScalarEvaluationEffects.effectOf(call)).isEqualTo(Effect.VOLATILE);
		} finally {
			FunctionRegistry.getInstance().remove(function);
		}
	}
}
